const raw = readFileSync(salesPath, 'utf8');
const rows = parseCsv(raw);
const issues = [];
const monthly = new Map();

for (const row of rows) {
  const date = new Date(row.date + 'T00:00:00Z');
  const amount = Number(row.amount);
  if (!row.date || Number.isNaN(date.getTime())) {
    issues.push(`line ${row.__line}: invalid date '${row.date}'`);
    continue;
  }
  if (row.amount === undefined || row.amount === '' || Number.isNaN(amount)) {
    issues.push(`line ${row.__line}: invalid amount '${row.amount}'`);
    continue;
  }
  const month = row.date.slice(0, 7);
  monthly.set(month, (monthly.get(month) ?? 0) + amount);
}

{
  "input": "sales.csv",
  "output": "monthly_summary.csv",
  "inputRows": 4,
  "validRows": 4,
  "skippedRows": 0,
  "issues": [],
  "months": 2,
  "summary": [
    {
      "month": "2026-01",
      "total_sales": 150,
      "mom_change": null
    },
    {
      "month": "2026-02",
      "total_sales": 210,
      "mom_change": "40.00%"
    }
  ],
  "outputExists": true
}

